import{z as n,x as A,o as l,c as d,q as t,j as r,D as e,d as o,s,S as B,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"加速器对比方法","description":"","frontmatter":{"title":"加速器对比方法","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/accelerator-comparison-method.md","filePath":"llm/accelerator-comparison-method.md","lastUpdated":1791063341000}'),p={name:"llm/accelerator-comparison-method.md"};function m(F,a,C,D,c,h){const i=A("Mermaid");return l(),d("div",null,[a[2]||(a[2]=t('<h1 id="加速器对比方法" tabindex="-1">加速器对比方法 <a class="header-anchor" href="#加速器对比方法" aria-label="Permalink to &quot;加速器对比方法&quot;">​</a></h1><div class="epigraph"><p>峰值 FLOPS 是厂商的屋顶；MFU、集体 busbw、编译时间和软件能否跑你的网格，才是你的屋顶。对比是多维测量，不是一列规格表排序。</p><footer>—— 屋顶线思想对照 Williams 等 Roofline；集体微基准见带宽模型课</footer></div><p><a href="/llm/chinese-accelerators">国产谱系</a> 把各栈画成四格。本课收束「通信与集群」：给出 <strong>同一把尺子</strong>，避免用 NVIDIA 的 TFLOPS 去除别人的 TFLOPS。缺口是方法，不是再介绍一家芯片。下一课程压缩进阶会用到这里的一维——哪种低精度核真实存在——但对比方法本身在本课讲完。后课默认你会：没有微基准与软件维的「赢」，只是营销。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>不可比的来源：精度不同（FP32 峰值对 FP8 峰值）、是否含稀疏、是否含稀疏 Tensor Core 的 2:4 假设、互连是否算进「平台 FLOPS」、batch 与序列是否相同、prefill 对 decode、训练对推理。再叠软件：有没有融合核、集体库拐点、框架并行实现。把这些压成一个加速比，决策会被单点演示绑架。</p><p><span class="marginnote">MFU（模型算力利用率）就是「实际有用计算 ÷ 峰值算力」：峰值是屋顶上写着的数，MFU 是你真用上了几成。一张峰值 1000 TFLOPS 的卡跑到 MFU 40%，就是每秒干 400 TFLOPS 的活——所以 MFU 40% 的卡完全可能赢过 MFU 只有 20% 的「更大」卡。</span></p><p>问题是固定 <strong>工作负载契约</strong>，再测多维：计算屋顶线、内存屋顶线、集体屋顶线、端到端 step 或 tokens/s、以及工程成本（人、编译、故障）。<a href="/llm/pretrain-comm">预训练通信</a> 与 <a href="/llm/nvlink">NVLink</a> 课已经示范过：同一条 All-Reduce 在不同链路上不是同一个数。对比加速器时，这条纪律推广到整机。</p><p><span class="marginnote">Roofline（Williams 等）用算术强度把计算墙和带宽墙画在一张图上。加速器对比至少要有「你的 kernel 落在哪一侧」，否则峰值比没有意义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>契约：模型（或代理层）、精度、batch、序列、并行网格、是否含数据加载与检查点。代理层要用真实消息大小的 GEMM 与集体，而不是只跑 LINPACK。</p><p><span class="marginnote">数字实例：8 卡节点做 All-Reduce，ring 算法下每卡要收发约 \\(2(N-1)/N\\) 倍数据量的消息。若一套栈的卡间带宽只有另一套的四分之一，这个集合操作就慢约 4 倍——即使两边计算峰值完全相同，训练 step time 也可能差出一大截，这正是「集体屋顶线」要单测的原因。</span></p><p>维度：</p><ol><li>单核 / 单卡 Roofline：算力 vs HBM vs 片上。</li><li>节点内互连 busbw（对标 NVLink 域，但用该栈的集体测试）。</li><li>跨节点集体拐点（\\(\\alpha\\)–\\(\\beta\\)）。</li><li>端到端：训练 step time 或 decode P99，含软件栈。</li><li>软件：内核覆盖、编译时间、框架成熟度、可观测性。</li><li>设施：功率、冷却、故障爆炸半径、调度 gang。</li><li>TCO：有效吞吐 / 瓦 / 元，用你测的吞吐，不用峰值。</li></ol>',13)),(l(),r(B,null,{default:e(()=>[s(i,{id:"mermaid-71",class:"mermaid",graph:"flowchart%20TD%0A%20%20CTR%5B%22%E5%B7%A5%E4%BD%9C%E8%B4%9F%E8%BD%BD%E5%A5%91%E7%BA%A6%22%5D%20--%3E%20RL%5B%22Roofline%22%5D%0A%20%20CTR%20--%3E%20COL%5B%22%E9%9B%86%E4%BD%93%20busbw%20%2F%20%E6%8B%90%E7%82%B9%22%5D%0A%20%20CTR%20--%3E%20E2E%5B%22%E7%AB%AF%E5%88%B0%E7%AB%AF%20SLA%22%5D%0A%20%20SW%5B%22%E8%BD%AF%E4%BB%B6%E6%88%90%E7%86%9F%E5%BA%A6%22%5D%20--%3E%20E2E%0A%20%20FAC%5B%22%E5%8A%9F%E7%8E%87%20%2F%20%E6%95%85%E9%9A%9C%E5%9F%9F%22%5D%20--%3E%20TCO%5B%22%E6%9C%89%E6%95%88%E5%90%9E%E5%90%90%E6%88%90%E6%9C%AC%22%5D%0A%20%20E2E%20--%3E%20TCO%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"禁止：把稀疏峰值当密模型成绩；把单卡 decode 乘卡数当线性扩展；把不同精度的 loss 质量当成同一工作负载。",-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"初学者容易以为「卡数乘单卡吞吐就是集群吞吐」。实际上扩展要打折：卡间通信等待、负载不均、故障重启都会吃掉收益——8 张卡常常只有 6、7 张卡的实际效果。这就是「不能把单卡 decode 乘卡数当线性扩展」背后的现实。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[o("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"端到端被最弱维卡住。一张卡 HBM 很强、集体很弱，则 TP 网格在该卡上不可行，只能 DP，于是对比变成网络对比。软件缺 All-to-All，则 MoE 不是该加速器的工作负载，应从契约里删掉或标为不支持，而不是给一个「N/A 当零」。确定性 LPU 与 GPU 必须在声明的 batch 下比 P99，不能比峰值吞吐。",-1)),(l(),r(B,null,{default:e(()=>[s(i,{id:"mermaid-84",class:"mermaid",graph:"flowchart%20TD%0A%20%20CARD%5B%22%E4%B8%80%E5%BC%A0%E5%8D%A1%EF%BC%9AHBM%20%E5%BC%BA%E3%80%81%E9%9B%86%E4%BD%93%E5%BC%B1%22%5D%20--%3E%20Q%7B%22%E8%83%BD%E5%90%A6%E8%B7%91%20TP%20%E7%BD%91%E6%A0%BC%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%EF%BC%9A%E5%8D%A1%E9%97%B4%E5%B8%A6%E5%AE%BD%E4%B8%8D%E5%A4%9F%22%7C%20DP%5B%22%E5%8F%AA%E8%83%BD%E9%80%80%E5%88%B0%E6%95%B0%E6%8D%AE%E5%B9%B6%E8%A1%8C%22%5D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20TP%5B%22%E5%BC%A0%E9%87%8F%E5%B9%B6%E8%A1%8C%E5%8F%AF%E8%A1%8C%22%5D%0A%20%20DP%20--%3E%20NET%5B%22%E5%AF%B9%E6%AF%94%E5%AE%9E%E9%99%85%E5%8F%98%E6%88%90%E7%BD%91%E7%BB%9C%E5%AF%B9%E6%AF%94%22%5D%0A%20%20SW%5B%22%E8%BD%AF%E4%BB%B6%E7%BC%BA%20All-to-All%20%E6%A0%B8%22%5D%20--%3E%20MOE%7B%22MoE%20%E8%83%BD%E8%B7%91%E5%90%97%EF%BC%9F%22%7D%0A%20%20MOE%20--%3E%7C%22%E5%90%A6%22%7C%20DEL%5B%22%E4%BB%8E%E5%A5%91%E7%BA%A6%E5%88%A0%E6%8E%89%E6%88%96%E6%A0%87%E4%B8%8D%E6%94%AF%E6%8C%81%22%5D%0A%20%20MOE%20--%3E%7C%22%E6%98%AF%22%7C%20KEEP%5B%22%E7%BA%B3%E5%85%A5%E7%AB%AF%E5%88%B0%E7%AB%AF%E6%B5%8B%E9%87%8F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p>测量本身有偏差：厂商容器开了特殊环境变量、关闭了数据加载。对比要固定镜像与参数，或明确「厂商最优 vs 默认同构实现」两行都报。</p><p><span class="marginnote">本站量化栏是金融微观结构，与权重量化无关。加速器对比里的「量化」指数值精度与 INT/FP 核，见下一课程。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>方法不产出唯一赢家。训练集群、decode 服务、端侧可以选三个不同答案。不要把本课当成采购结论。通信与集群课程结束；下一课从均匀量化格子开始，因为对比里反复出现的「有没有 INT4/FP8 核」需要格子本身的语言。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>先锁工作负载契约，再测 Roofline、集体、端到端、软件、设施、TCO。</li><li>峰值 FLOPS 与稀疏营销必须从主表拿开。</li><li>最弱维决定网格是否可行；缺集体就标不支持。</li><li>用自测吞吐算成本，不用规格表。</li><li>出处：Roofline；集体微基准与前序通信课；各栈公开文档只作规格上限。</li></ul>',6))])}const f=n(p,[["render",m]]);export{T as __pageData,f as default};
